def parse_csv_line(line):
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # quoted field
            i += 1
            start = i
            field_chars = []
            while i < n:
                if line[i] == '"':
                    # check if escaped
                    if i+1 < n and line[i+1] == '"':
                        field_chars.append('"')
                        i += 2
                    else:
                        # closing quote
                        i += 1
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            else:
                raise ValueError('Quoted field with no closing quote')
            # after closing quote, must be comma or end
            if i < n and line[i] != ',':
                raise ValueError('Invalid character after closing quote')
            fields.append(''.join(field_chars))
            if i < n:
                # skip comma
                i += 1
        else:
            # unquoted field
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError('Double quote in unquoted field')
                i += 1
            fields.append(line[start:i])
            if i < n:
                # skip comma
                i += 1
    # handle trailing comma (empty field after last comma)
    if line.endswith(','):
        fields.append('')
    # handle empty line
    if line == '':
        return ['']
    return fields

