def test():
    test_cases = [
        ('a,b,c', ['a','b','c']),
        ('"a,b",c', ['a,b','c']),
        ('"""say ""hi""",x', ['say "hi"','x']),  # Need correct input: '"say ""hi""",x'
        ('', ['']),
        ('a"b', None),  # expect ValueError
        ('"unclosed', None),  # ValueError
        ('"a",b', ['a','b']),
        ('"a,,b",c', ['a,,b','c']),
        ('a,b,', ['a','b','']),
        (',a,b', ['','a','b']),
        ('""', ['']),  # empty quoted field
        ('"""",', ['"', '']),  # quote then comma? Actually field containing a quote: """", -> field is '"' then empty? Let's skip.
    ]
    for inp, expected in test_cases:
        try:
            result = parse_csv_line(inp)
            if expected is None:
                print(f'FAIL: {inp!r} expected ValueError but got {result}')
                return
            if result != expected:
                print(f'FAIL: {inp!r} expected {expected} got {result}')
                return
        except ValueError as e:
            if expected is None:
                # expected error, ok
                continue
            else:
                print(f'FAIL: {inp!r} unexpected ValueError: {e}')
                return
    print('ALL TESTS PASSED')

